// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address baseToken, address nft) public {
        vm.assume(baseToken != nft);
        c.initialize(
            baseToken,
            nft,
            uint128(bound(uint256(uint160(nft)), 0, type(uint128).max)),
            uint128(bound(uint256(uint160(baseToken)), 0, type(uint128).max)),
            uint56(bound(uint256(uint160(nft)), 0, type(uint56).max)),
            uint16(bound(uint256(uint160(baseToken)), 0, 5_000)),
            keccak256(abi.encodePacked(baseToken, nft)),
            uint256(uint160(baseToken)) % 2 == 0,
            uint256(uint160(nft)) % 2 == 0
        );
        assertTrue(c.nft() == nft);
    }
}

